// Port of app/domain/answering/pseudonymize.py (SPEC-001 R4, CHG-001 D2).
const EMAIL = /[\p{L}\p{N}_.+-]+@[\p{L}\p{N}_-]+(?:\.[\p{L}\p{N}_-]+)+/gu;
const NIE = /(?<![\p{L}\p{N}_])[XYZxyz][\s-]?\p{Nd}{7}[\s-]?[A-Za-z](?![\p{L}\p{N}_])/gu;
const DNI = /(?<![\p{L}\p{N}_])\p{Nd}{8}[\s-]?[A-Za-z](?![\p{L}\p{N}_])/gu;
const PHONE = /(?<![\p{L}\p{N}_+])(?:(?:\+|00)34[\s.-]?)?[6789]\p{Nd}{2}(?:[\s.-]?\p{Nd}){6}(?![\p{L}\p{N}_])/gu;
const NAME_INTRO = /(?<![\p{L}\p{N}_])(?:me\s+llamo|mi\s+nombre\s+es|a\s+nombre\s+de)\s+/giu;
const WORD = /[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+/y;
const SPACES = /\s+/y;
const NAME_CONNECTORS = new Set(['de', 'del', 'la', 'las', 'los']);
const MAX_NAME_WORDS = 4;
const NOT_A_SURNAME = new Set([
  'y', 'e', 'o', 'u', 'que', 'quiero', 'quisiera', 'querría', 'para', 'por', 'con', 'sin',
  'de', 'del', 'la', 'el', 'los', 'las', 'un', 'una', 'tengo', 'necesito', 'me', 'mi',
  'a', 'al', 'en', 'es', 'soy', 'pero', 'porque', 'gracias', 'hola', 'buenas', 'buenos',
  'cuánto', 'cuanto', 'cómo', 'como', 'qué', 'cuándo', 'cuando', 'pido', 'pedir',
]);

function matchAt(re, text, pos) {
  re.lastIndex = pos;
  const m = re.exec(text);
  return m ? { text: m[0], end: pos + m[0].length } : null;
}
const isUpperChar = (c) => c !== c.toLowerCase();
const isLowerWord = (w) => w === w.toLowerCase() && w !== w.toUpperCase();

function capitalizedNameEnd(text, first) {
  let end = first.end;
  let words = 1;
  let cursor = first.end;
  while (words < MAX_NAME_WORDS) {
    let connectorsEnd = cursor;
    let word = null;
    while (true) {
      const gap = matchAt(SPACES, text, connectorsEnd);
      word = gap ? matchAt(WORD, text, gap.end) : null;
      if (word && NAME_CONNECTORS.has(word.text.toLowerCase())) {
        connectorsEnd = word.end;
        continue;
      }
      break;
    }
    if (!word || !isUpperChar(word.text[0])) break;
    end = cursor = word.end;
    words += 1;
  }
  return end;
}

function lowercaseNameEnd(text, first) {
  if (NOT_A_SURNAME.has(first.text.toLowerCase())) return null;
  const gap = matchAt(SPACES, text, first.end);
  const second = gap ? matchAt(WORD, text, gap.end) : null;
  if (second && isLowerWord(second.text) && !NOT_A_SURNAME.has(second.text)) return second.end;
  return first.end;
}

function nameEnd(text, start) {
  const first = matchAt(WORD, text, start);
  if (!first) return null;
  return isUpperChar(first.text[0]) ? capitalizedNameEnd(text, first) : lowercaseNameEnd(text, first);
}

function replaceNames(text) {
  let out = '';
  let pos = 0;
  NAME_INTRO.lastIndex = 0;
  let intro;
  while ((intro = NAME_INTRO.exec(text)) !== null) {
    const introEnd = intro.index + intro[0].length;
    if (intro.index < pos) continue;
    const end = nameEnd(text, introEnd);
    if (end === null) continue;
    out += text.slice(pos, introEnd) + '[NOMBRE]';
    pos = end;
  }
  return out + text.slice(pos);
}

function pseudonymize(text) {
  let t = text.replace(EMAIL, '[EMAIL]');
  t = t.replace(NIE, '[DNI]');
  t = t.replace(DNI, '[DNI]');
  t = t.replace(PHONE, '[TELEFONO]');
  return replaceNames(t);
}

const msg = $json.message ?? {};
return { json: { chatId: msg.chat?.id, question: pseudonymize(msg.text ?? '') } };

// SPEC-005 P6: B returns no identifier; A attaches its own chat id to B's reply fields.
// SPEC-006: also sets the keyboard for "¿Qué teclado?".
return { json: { ...$json, chatId: $('Seudonimizar').item.json.chatId, keyboard: $json.handoff ? 'handoff' : 'none' } };

// SPEC-006 consent module (specs/006-consent/spec.md, plan.md Step 1).
// Paste-ready: the n8n Code nodes "Clasificar" and "Decidir" of lifecenter-telegram-demo carry this
// exact code followed only by their input/output wiring (C23). No require, no network, no state.

// --- Configuration (C22). Change the version whenever CONSENT_NOTICE changes: everyone is asked again.
const CONSENT_TEXT_VERSION = '1';

// --- Fixed texts (spec "Fixed texts", approved by the human 2026-11-21) ---
const CONSENT_NOTICE =
  'Hola, soy el asistente de LifeCenter. Para responderte: quito tu nombre, teléfono, DNI y email ' +
  'de los mensajes antes de procesarlos; envío la consulta a un modelo de IA externo (Gemini, de ' +
  'Google), y guardo el recorrido de cada consulta, sin tus datos, durante 30 días. Si me cuentas un ' +
  'síntoma te daré siempre el teléfono de la clínica. Esto es una demostración: no escribas datos ' +
  'reales. ¿Aceptas?';
const ACCEPTED_TEXT = 'Gracias. Ya puedes escribirme tu consulta.';
const REJECTED_TEXT =
  'De acuerdo, no procesaré tus consultas. Puedes llamar a recepción. Si cambias de opinión, escribe /privacidad.';
const REVOKED_TEXT =
  'He retirado tu consentimiento. No procesaré más consultas tuyas. Si cambias de opinión, escribe /privacidad.';
const STATUS_ACCEPTED = 'Estado: aceptaste este aviso el {fecha}.';
const STATUS_NONE = 'Estado: no has aceptado este aviso.';
// Copies of CHG-001 texts this module now composes: D7 (error) and D12 (no text).
const ERROR_TEXT = 'Ahora mismo no puedo responder. ¿Quieres que pase tu consulta a recepción?';
const TEXT_ONLY_TEXT = 'Solo puedo leer mensajes de texto. ¿Me escribes tu consulta?';

// --- Buttons (C7): labels and callback_data, each at most 64 bytes ---
const BUTTON_LABELS = {
  handoff: 'Hablar con recepción',
  accept: 'Acepto',
  reject: 'No acepto',
  withdraw: 'Retirar consentimiento',
};
const CALLBACK_HANDOFF = 'handoff';
const CALLBACK_WITHDRAW = 'consent:withdraw';
const callbackAccept = (version = CONSENT_TEXT_VERSION) => `consent:accept:${version}`;
const callbackReject = (version = CONSENT_TEXT_VERSION) => `consent:reject:${version}`;

// --- Commands (spec "Command"): exactly /start or /privacidad, optionally @<bot>, spaces ignored,
// in any letter case (phone keyboards capitalize the first letter) ---
const COMMAND = /^\s*\/(start|privacidad)(?:@[A-Za-z0-9_]+)?\s*$/i;
function parseCommand(text) {
  const m = COMMAND.exec(typeof text === 'string' ? text : '');
  return m ? m[1].toLowerCase() : null;
}

// --- Buttons: callback_data → { kind, version } ---
const CONSENT_CALLBACK = /^consent:(accept|reject):(.+)$/;
function parseCallback(data) {
  if (data === CALLBACK_HANDOFF) return { kind: 'handoff', version: null };
  if (data === CALLBACK_WITHDRAW) return { kind: 'withdraw', version: null };
  const m = CONSENT_CALLBACK.exec(typeof data === 'string' ? data : '');
  return m ? { kind: m[1], version: m[2] } : { kind: 'unknown_button', version: null };
}

// --- A Telegram update → route. fromId is a string: it is only ever passed to Neon as $1 (C18). ---
function classifyUpdate(update) {
  const asId = (v) => (v === undefined || v === null ? null : String(v));
  const cq = update && update.callback_query;
  if (cq) {
    const { kind, version } = parseCallback(cq.data);
    return {
      kind,
      fromId: asId(cq.from && cq.from.id),
      chatId: cq.message && cq.message.chat ? cq.message.chat.id : null,
      callbackQueryId: cq.id === undefined ? null : cq.id,
      version,
    };
  }
  const m = (update && update.message) || {};
  const hasText = typeof m.text === 'string' && m.text !== '';
  const command = hasText ? parseCommand(m.text) : null;
  return {
    kind: command || (hasText ? 'text' : 'other'),
    fromId: asId(m.from && m.from.id),
    chatId: m.chat ? m.chat.id : null,
    callbackQueryId: null,
    version: null,
  };
}

// --- Consent in force (C22): accepted with the current version; anything else is no consent ---
function isConsentInForce(row) {
  return !!row && row.status === 'accepted' && row.text_version === CONSENT_TEXT_VERSION;
}

// --- dd/mm/aaaa in Europe/Madrid ---
function formatDate(decidedAt) {
  const parts = new Intl.DateTimeFormat('es-ES', {
    timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit', year: 'numeric',
  }).formatToParts(new Date(decidedAt));
  const get = (type) => parts.find((p) => p.type === type).value;
  return `${get('day')}/${get('month')}/${get('year')}`;
}

// --- What to do with an update (plan Step 1, decision table; C2–C16) ---
// urgency: the output of "Detectar urgencia" (B's wiring), or null if it did not run.
// consent: the row from consent_get ({} when there is none); lookupFailed: the lookup errored.
function decide({ route, urgency, consent, lookupFailed }) {
  const reply = (text, keyboard) => ({ action: 'reply', text, keyboard });
  const notice = reply(CONSENT_NOTICE, 'consent');
  const inForce = !lookupFailed && isConsentInForce(consent);
  const kind = route && route.kind;

  if (kind === 'handoff') throw new Error('decide(): the handoff button has its own branch (C12)');
  if (kind === 'text') {
    if (inForce) return { action: 'core', text: null, keyboard: null };
    if (urgency && urgency.urgency_level && urgency.urgency_level !== 'none') return reply(urgency.text, 'handoff');
    return lookupFailed ? reply(ERROR_TEXT, 'handoff') : notice;
  }
  if (lookupFailed) return reply(ERROR_TEXT, 'handoff');

  const withStatus = (status, keyboard) => reply(`${CONSENT_NOTICE}\n\n${status}`, keyboard);
  switch (kind) {
    case 'other':
      return inForce ? reply(TEXT_ONLY_TEXT, 'none') : notice;
    case 'start':
    case 'privacidad':
      if (inForce) return withStatus(STATUS_ACCEPTED.replace('{fecha}', formatDate(consent.decided_at)), 'withdraw');
      return kind === 'start' ? notice : withStatus(STATUS_NONE, 'consent');
    case 'accept':
      return route.version === CONSENT_TEXT_VERSION ? { action: 'accept', text: ACCEPTED_TEXT, keyboard: 'none' } : notice;
    case 'reject':
      return route.version === CONSENT_TEXT_VERSION ? reply(REJECTED_TEXT, 'none') : notice;
    case 'withdraw':
      return { action: 'withdraw', text: REVOKED_TEXT, keyboard: 'none' };
    case 'unknown_button':
      return notice;
    default:
      throw new Error(`decide(): unknown route kind "${kind}"`);
  }
}

// --- n8n wiring ("Clasificar", SPEC-006 C23): keep the update as it is and add the route ---
return { json: { ...$json, route: classifyUpdate($json) } };

// SPEC-003 urgency detector (specs/004-urgencies/plan.md). Deterministic: no LLM, no network.
// Paste-ready for the n8n Code node "Detectar urgencia": no require/module/export here; the node
// appends only its input/output wiring (U16). Tested by n8n/code/urgencias.test.js.

// --- Configuration (U13) — the clinic's urgency phone. Example value until DEP-01. ---
const URGENCY_PHONE = '000 000 000';
const URGENCY_PHONE_IS_EXAMPLE = true;

// --- Fixed texts (spec "Fixed texts"; approved by the human 2026-11-19; pending clinical review) ---
const URGENT_MESSAGE =
  `No puedo valorar síntomas por aquí. Llama a la clínica al ${URGENCY_PHONE}. ` +
  'Si es grave o tienes dificultad para respirar, llama al 112.';
const SEVERE_MESSAGE =
  'Si tienes dificultad para respirar o tragar, una hemorragia que no para o te has dado un golpe ' +
  'fuerte en la cara o la cabeza, llama ahora al 112. No puedo valorar síntomas por aquí. ' +
  `Si no es una emergencia, llama a la clínica al ${URGENCY_PHONE}.`;
const EXAMPLE_PHONE_NOTICE =
  '(Este teléfono es de ejemplo: todavía no tenemos el número real de la clínica.)';

// --- Question flag and normalization (U10) ---
// The flag is read on the raw (pseudonymized) text, before normalize() removes punctuation.
function isQuestion(text) {
  return /[¿?]/.test(String(text ?? ''));
}

// Lowercase, no accents, SPEC-001 placeholders removed, punctuation removed, single spaces.
function normalize(text) {
  return String(text ?? '')
    .toLowerCase()
    .normalize('NFD').replace(/\p{M}+/gu, '')
    .replace(/\[(nombre|telefono|dni|email)\]/g, ' ')
    .replace(/[^\p{L}\p{N}\s]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// --- Rule tables (provisional clinical criteria, clarifications A1/A3; pending Prince Calderon).
// Every pattern works on normalize()d text. A rule with several patterns needs all of them. ---
const SWELLING = /\b(hinch\w*|inflam\w*)\b/;
const BLEEDING = /\bsangr\w*/;
const BLOW = /\b(golpe\w*|caida|me cai|me he caido|se ha caido|accidente|traumatismo)\b/;

// Removed from the text before classifying (U8).
const FIGURATIVE = [
  { id: 'fig_duele_que', re: /\b(?:me |te |nos )?duele (?:pensar|pagar|gastar|tener que|que|ver|saber|el bolsillo|la cartera)\b/g },
  { id: 'fig_de_golpe', re: /\bde golpe\b/g },
  { id: 'fig_me_muero_de', re: /\bme muero de (?:ganas|risa)\b/g },
];

// A1 — severe signs.
const SEVERE_RULES = [
  { id: 'sev_breath_swallow', all: [/\b(?:no puedo|me cuesta|le cuesta|dificultad para|no consigo|no puede)(?: \w+)? (?:respirar|tragar)\b/] },
  { id: 'sev_swelling_neck_eye', all: [SWELLING, /\b(?:cuello|ojo|ojos|no puedo abrir)\b/] },
  { id: 'sev_bleeding_nonstop', all: [BLEEDING, /\b(?:no para|no se para|no deja de|sin parar|no se corta|a chorro)\b/] },
  { id: 'sev_blow_face_head', all: [BLOW, /\b(?:cara|cabeza|mandibula)\b/] },
  { id: 'sev_blow_unconscious', all: [BLOW, /\b(?:desmay\w*|conocimiento|inconsciente)\b/] },
  { id: 'sev_blow_tooth_out', all: [BLOW, /\b(?:se me ha caido|se le ha caido|arrancado)(?: \w+)? (?:un |el )?(?:diente|muela)\b/] },
  { id: 'sev_fever_swelling', all: [/\bfiebre\b/, SWELLING] },
];

// A3 — symptom terms.
const SYMPTOM_TERMS = [
  { id: 'sym_pain', all: [/\b(?:dolor\w*|duele|duelen|doler|dolera|doloros\w*|molest\w*|pinchazo\w*)\b/] },
  { id: 'sym_bleeding', all: [BLEEDING] },
  { id: 'sym_swelling', all: [SWELLING] },
  { id: 'sym_fever', all: [/\bfiebre\b/] },
  { id: 'sym_infection', all: [/\b(?:pus|absces\w*|flemon\w*|infecc\w*)\b/] },
  { id: 'sym_blow', all: [/\b(?:golpe\w*|traumatismo)\b/] },
  { id: 'sym_tooth_damage', all: [
    /\b(?:diente|dientes|muela|muelas|corona|empaste|funda|puente)\b/,
    /\b(?:roto|rota|partido|partida|caido|caida|se mueve|se me mueve|suelto|suelta|flojo|floja|movido)\b/,
  ] },
];

// Hypothetical forms about a treatment: they take precedence over "me" (plan, step 4).
const HYPOTHETICAL = [
  /\b(?:me |te )?(?:va|van) a doler\b/g,
  /\bdolera\b/g,
  /\bes doloros[oa]\b/g,
  /\bduele mucho (?:la|el)\b/g,
];

// Signs that the patient reports an own, current or recent state.
const PERSONAL_MARKERS = [
  /\bme (?:duele\w*|sangr\w*|molest\w*|hinch\w*|ha|he|han|esta\w*|noto|sale|cuesta|di|hicieron|pusieron)\b/,
  /\bmis?\b/,
  /\b(?:tengo|tiene|estoy|llevo|lleva|noto|sigue)\b/,
  /\bse (?:me|le)\b/,
  /\bdesde (?:ayer|hace|esta|el|que)\b/,
  /\b(?:hoy|anoche|ahora)\b/,
];

const TREATMENT_WORDS =
  /\b(?:limpieza|blanqueamiento|ortodoncia|implantes?|endodoncia|extraccion|empastes?|tratamiento|anestesia|revision|radiografia|brackets)\b/;

function firing(rules, text) {
  return rules.filter((r) => r.all.every((re) => re.test(text))).map((r) => r.id);
}

// --- Classification (U5–U9) ---
function detectUrgency(text) {
  const question = isQuestion(text);
  let t = normalize(text);
  const matched = [];

  for (const f of FIGURATIVE) {
    if (f.re.test(t)) {
      matched.push(f.id);
      f.re.lastIndex = 0;
      t = t.replace(f.re, ' ').replace(/\s+/g, ' ').trim();
    }
    f.re.lastIndex = 0;
  }

  const severe = firing(SEVERE_RULES, t);
  if (severe.length) return { level: 'severe', matched: matched.concat(severe), question };

  const symptoms = firing(SYMPTOM_TERMS, t);
  if (!symptoms.length) return { level: 'none', matched, question };
  matched.push(...symptoms);

  let withoutHypothetical = t;
  let hypothetical = false;
  for (const re of HYPOTHETICAL) {
    re.lastIndex = 0;
    if (re.test(withoutHypothetical)) {
      hypothetical = true;
      re.lastIndex = 0;
      withoutHypothetical = withoutHypothetical.replace(re, ' ');
    }
    re.lastIndex = 0;
  }
  const personal = PERSONAL_MARKERS.some((re) => re.test(withoutHypothetical));
  if (!personal && TREATMENT_WORDS.test(t) && (question || hypothetical)) {
    matched.push(hypothetical ? 'info_hypothetical' : 'info_question');
    return { level: 'none', matched, question };
  }

  matched.push(personal ? 'reported_state' : 'doubt');
  return { level: 'urgent', matched, question };
}

// --- Reply (U11–U13): fixed text only, built from the level, never from the message. ---
function composeUrgencyReply(level) {
  const base = level === 'severe' ? SEVERE_MESSAGE : URGENT_MESSAGE;
  return URGENCY_PHONE_IS_EXAMPLE ? `${base}\n\n${EXAMPLE_PHONE_NOTICE}` : base;
}

// --- n8n wiring (U16; SPEC-005: no chat id in the core workflow) ---
const r = detectUrgency($json.question);
if (r.level === 'none') return { json: { question: $json.question, urgency_level: 'none' } };
return { json: {
  text: composeUrgencyReply(r.level), handoff: true,
  reason: 'urgency', urgency_level: r.level, matched: r.matched,
} };

// SPEC-006 consent module (specs/006-consent/spec.md, plan.md Step 1).
// Paste-ready: the n8n Code nodes "Clasificar" and "Decidir" of lifecenter-telegram-demo carry this
// exact code followed only by their input/output wiring (C23). No require, no network, no state.

// --- Configuration (C22). Change the version whenever CONSENT_NOTICE changes: everyone is asked again.
const CONSENT_TEXT_VERSION = '1';

// --- Fixed texts (spec "Fixed texts", approved by the human 2026-11-21) ---
const CONSENT_NOTICE =
  'Hola, soy el asistente de LifeCenter. Para responderte: quito tu nombre, teléfono, DNI y email ' +
  'de los mensajes antes de procesarlos; envío la consulta a un modelo de IA externo (Gemini, de ' +
  'Google), y guardo el recorrido de cada consulta, sin tus datos, durante 30 días. Si me cuentas un ' +
  'síntoma te daré siempre el teléfono de la clínica. Esto es una demostración: no escribas datos ' +
  'reales. ¿Aceptas?';
const ACCEPTED_TEXT = 'Gracias. Ya puedes escribirme tu consulta.';
const REJECTED_TEXT =
  'De acuerdo, no procesaré tus consultas. Puedes llamar a recepción. Si cambias de opinión, escribe /privacidad.';
const REVOKED_TEXT =
  'He retirado tu consentimiento. No procesaré más consultas tuyas. Si cambias de opinión, escribe /privacidad.';
const STATUS_ACCEPTED = 'Estado: aceptaste este aviso el {fecha}.';
const STATUS_NONE = 'Estado: no has aceptado este aviso.';
// Copies of CHG-001 texts this module now composes: D7 (error) and D12 (no text).
const ERROR_TEXT = 'Ahora mismo no puedo responder. ¿Quieres que pase tu consulta a recepción?';
const TEXT_ONLY_TEXT = 'Solo puedo leer mensajes de texto. ¿Me escribes tu consulta?';

// --- Buttons (C7): labels and callback_data, each at most 64 bytes ---
const BUTTON_LABELS = {
  handoff: 'Hablar con recepción',
  accept: 'Acepto',
  reject: 'No acepto',
  withdraw: 'Retirar consentimiento',
};
const CALLBACK_HANDOFF = 'handoff';
const CALLBACK_WITHDRAW = 'consent:withdraw';
const callbackAccept = (version = CONSENT_TEXT_VERSION) => `consent:accept:${version}`;
const callbackReject = (version = CONSENT_TEXT_VERSION) => `consent:reject:${version}`;

// --- Commands (spec "Command"): exactly /start or /privacidad, optionally @<bot>, spaces ignored,
// in any letter case (phone keyboards capitalize the first letter) ---
const COMMAND = /^\s*\/(start|privacidad)(?:@[A-Za-z0-9_]+)?\s*$/i;
function parseCommand(text) {
  const m = COMMAND.exec(typeof text === 'string' ? text : '');
  return m ? m[1].toLowerCase() : null;
}

// --- Buttons: callback_data → { kind, version } ---
const CONSENT_CALLBACK = /^consent:(accept|reject):(.+)$/;
function parseCallback(data) {
  if (data === CALLBACK_HANDOFF) return { kind: 'handoff', version: null };
  if (data === CALLBACK_WITHDRAW) return { kind: 'withdraw', version: null };
  const m = CONSENT_CALLBACK.exec(typeof data === 'string' ? data : '');
  return m ? { kind: m[1], version: m[2] } : { kind: 'unknown_button', version: null };
}

// --- A Telegram update → route. fromId is a string: it is only ever passed to Neon as $1 (C18). ---
function classifyUpdate(update) {
  const asId = (v) => (v === undefined || v === null ? null : String(v));
  const cq = update && update.callback_query;
  if (cq) {
    const { kind, version } = parseCallback(cq.data);
    return {
      kind,
      fromId: asId(cq.from && cq.from.id),
      chatId: cq.message && cq.message.chat ? cq.message.chat.id : null,
      callbackQueryId: cq.id === undefined ? null : cq.id,
      version,
    };
  }
  const m = (update && update.message) || {};
  const hasText = typeof m.text === 'string' && m.text !== '';
  const command = hasText ? parseCommand(m.text) : null;
  return {
    kind: command || (hasText ? 'text' : 'other'),
    fromId: asId(m.from && m.from.id),
    chatId: m.chat ? m.chat.id : null,
    callbackQueryId: null,
    version: null,
  };
}

// --- Consent in force (C22): accepted with the current version; anything else is no consent ---
function isConsentInForce(row) {
  return !!row && row.status === 'accepted' && row.text_version === CONSENT_TEXT_VERSION;
}

// --- dd/mm/aaaa in Europe/Madrid ---
function formatDate(decidedAt) {
  const parts = new Intl.DateTimeFormat('es-ES', {
    timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit', year: 'numeric',
  }).formatToParts(new Date(decidedAt));
  const get = (type) => parts.find((p) => p.type === type).value;
  return `${get('day')}/${get('month')}/${get('year')}`;
}

// --- What to do with an update (plan Step 1, decision table; C2–C16) ---
// urgency: the output of "Detectar urgencia" (B's wiring), or null if it did not run.
// consent: the row from consent_get ({} when there is none); lookupFailed: the lookup errored.
function decide({ route, urgency, consent, lookupFailed }) {
  const reply = (text, keyboard) => ({ action: 'reply', text, keyboard });
  const notice = reply(CONSENT_NOTICE, 'consent');
  const inForce = !lookupFailed && isConsentInForce(consent);
  const kind = route && route.kind;

  if (kind === 'handoff') throw new Error('decide(): the handoff button has its own branch (C12)');
  if (kind === 'text') {
    if (inForce) return { action: 'core', text: null, keyboard: null };
    if (urgency && urgency.urgency_level && urgency.urgency_level !== 'none') return reply(urgency.text, 'handoff');
    return lookupFailed ? reply(ERROR_TEXT, 'handoff') : notice;
  }
  if (lookupFailed) return reply(ERROR_TEXT, 'handoff');

  const withStatus = (status, keyboard) => reply(`${CONSENT_NOTICE}\n\n${status}`, keyboard);
  switch (kind) {
    case 'other':
      return inForce ? reply(TEXT_ONLY_TEXT, 'none') : notice;
    case 'start':
    case 'privacidad':
      if (inForce) return withStatus(STATUS_ACCEPTED.replace('{fecha}', formatDate(consent.decided_at)), 'withdraw');
      return kind === 'start' ? notice : withStatus(STATUS_NONE, 'consent');
    case 'accept':
      return route.version === CONSENT_TEXT_VERSION ? { action: 'accept', text: ACCEPTED_TEXT, keyboard: 'none' } : notice;
    case 'reject':
      return route.version === CONSENT_TEXT_VERSION ? reply(REJECTED_TEXT, 'none') : notice;
    case 'withdraw':
      return { action: 'withdraw', text: REVOKED_TEXT, keyboard: 'none' };
    case 'unknown_button':
      return notice;
    default:
      throw new Error(`decide(): unknown route kind "${kind}"`);
  }
}

